<script setup lang="ts">import {computed,onMounted,ref,watch} from 'vue'; import {useRoute} from 'vue-router'; import {ElMessage} from 'element-plus'; import {api} from '../api'; const route=useRoute(); const rows=ref<any[]>([]); const loading=ref(false); const dialog=ref(false); const payload=ref('{}'); const resource=computed(()=>String(route.params.resource)); const labels:Record<string,string>={standards:'椋熸潗鏍囧噯搴?,suppliers:'渚涘簲鍟?,plans:'閲囪喘璁″垝',inquiries:'璇环/绔炰环',orders:'閲囪喘璁㈠崟',deliveries:'閰嶉€?,inspections:'鏅鸿兘楠屾敹',inventory:'搴撳瓨鎵规',settlements:'缁撶畻'}; async function load(){loading.value=true;try{rows.value=(await api.get('/'+resource.value)).data}finally{loading.value=false}} async function create(){try{await api.post('/'+resource.value,JSON.parse(payload.value));dialog.value=false;await load();ElMessage.success('宸蹭繚瀛?)}catch(e){ElMessage.error('淇濆瓨澶辫触锛氳妫€鏌ュ繀濉瓧娈点€丣SON 鏍煎紡鍜岃鑹叉潈闄?)}} onMounted(load);watch(resource,load);</script><template><div class="bar"><h1>{{labels[resource]||resource}}</h1><div><el-button type="primary" @click="dialog=true">鏂板</el-button><el-button @click="load">鍒锋柊</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="key in (rows[0]?Object.keys(rows[0]):['id'])" :key="key" :prop="key" :label="key" min-width="150"/></el-table><el-dialog v-model="dialog" :title="'鏂板'+(labels[resource]||resource)" width="600"><p>杈撳叆绗﹀悎鎺ュ彛瀛楁鐨?JSON 鏁版嵁銆?/p><el-input v-model="payload" type="textarea" :rows="12"/><template #footer><el-button @click="dialog=false">鍙栨秷</el-button><el-button type="primary" @click="create">淇濆瓨</el-button></template></el-dialog></template><style scoped>.bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}</style>

